// generate a fresh number every tick and forward it to B
const num = Math.floor(Math.random() * 100);
ctx.log('generated ' + num);

// ctx.responses holds whatever B sent BACK last tick (one tick behind, per the
// engine's response-packet rule) - show it in the right-side badge if present
let rightBadge = null;
if (ctx.responses.length > 0) {
  const resp = ctx.responses[0];
  ctx.log('B responded: ' + resp.value + ' (from ' + resp.fromLabel + ')');
  rightBadge = { text: String(resp.value), color: '#2f6fed' };
}

// left badge is purely opt-in (same as right badge) - explicitly show the number
// just sent, so it's visible alongside whatever B responded with
return { value: num, state: {}, leftBadge: { text: String(num), color: '#2f8f4e' }, rightBadge };

// receive A's number
if (ctx.inputs.length === 0 || ctx.inputs[0].value === undefined) return { value: null, state: {} };
const received = ctx.inputs[0].value;

// append a random letter and forward the combined value to C
const letters = 'abcdefghijklmnopqrstuvwxyz';
const letter = letters[Math.floor(Math.random() * letters.length)];
const combined = String(received) + letter;
ctx.log('received ' + received + ' from ' + ctx.inputs[0].fromLabel + ', forwarding ' + combined);

// acknowledge A's number with a response (broadcasts back to whoever sent this part
// forward data this tick - just A here)
const responseToA = 'ack:' + combined;

// show whatever C sent back last tick in the right-side badge
let rightBadge = null;
if (ctx.responses.length > 0) {
  const resp = ctx.responses[0];
  ctx.log('C responded: ' + resp.value + ' (from ' + resp.fromLabel + ')');
  rightBadge = { text: String(resp.value), color: '#8e44ad' };
}

// left badge is purely opt-in (same as right badge) - explicitly show the combined
// value just forwarded
return { value: combined, state: {}, response: responseToA, leftBadge: { text: combined, color: '#2f8f4e' }, rightBadge };

// receive B's value
if (ctx.inputs.length === 0 || ctx.inputs[0].value === undefined) return { value: null, state: {} };
const received = ctx.inputs[0].value;
ctx.log('received ' + received + ' from ' + ctx.inputs[0].fromLabel);

// respond to B with a random number (broadcasts back to whoever sent this part
// forward data this tick - just B here)
const randomResponse = Math.floor(Math.random() * 1000);
ctx.log('responding with ' + randomResponse);

// left badge is purely opt-in (same as right badge) - explicitly show the value just
// received
return {
  value: received,
  state: {},
  response: randomResponse,
  leftBadge: { text: String(received), color: '#2f8f4e' },
  rightBadge: { text: String(received), color: '#16a34a' },
};
